arguments.new_string:
default_type application/octet-stream;

log_format benchmark '$time_local "$request_method" $status "$http_user_agent"';
limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;

arguments.content:
server {
	listen 8080;
	server_name localhost;

	root /var/www/html;
	index index.html;

	access_log /var/log/nginx/benchmark-access.log benchmark;
	error_log /var/log/nginx/benchmark-error.log;

	limit_req zone=benchmark_limit burst=10;
	error_page 404 /404.html;

	location / {
		try_files $uri $uri/ =404;
	}

	location = /404.html {
		internal;
	}
}

arguments.command:
set -eu
mkdir -p /etc/nginx/conf.d /var/www/html /var/log/nginx
python3 - <<'PY'
from pathlib import Path

path = Path('/etc/nginx/nginx.conf')
text = path.read_text()
if 'log_format benchmark ' not in text:
    needle = '\tdefault_type application/octet-stream;\n'
    if needle not in text:
        raise SystemExit('nginx.conf insertion point not found')
    text = text.replace(
        needle,
        needle + '\n\tlog_format benchmark \'$time_local "\\$request_method" $status "\\$http_user_agent"\';\n'
        .replace('\\$', '$')
        + '\tlimit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;\n',
        1,
    )
path.write_text(text)
PY
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
	listen 8080;
	server_name localhost;

	root /var/www/html;
	index index.html;

	access_log /var/log/nginx/benchmark-access.log benchmark;
	error_log /var/log/nginx/benchmark-error.log;

	limit_req zone=benchmark_limit burst=10;
	error_page 404 /404.html;

	location / {
		try_files $uri $uri/ =404;
	}

	location = /404.html {
		internal;
	}
}
EOF
printf '%s\n' 'Welcome to the benchmark webserver' > /var/www/html/index.html
printf '%s\n' 'Page not found - Please check your URL' > /var/www/html/404.html
if [ -e /etc/nginx/sites-enabled/default ] || [ -L /etc/nginx/sites-enabled/default ]; then
    unlink /etc/nginx/sites-enabled/default
fi

